export function Rhythm({
  consistent = {{consistent}},
  spacing = {{spacing}},
  accent = "{{accent}}",
  barCount = "{{barCount}}",
}) {
  const bar = { height: 26, background: accent, borderRadius: 6, display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 700 };
  const gaps = consistent ? [spacing, spacing, spacing, spacing] : [6, 28, 10, 22];
  const n = Number(barCount);
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", width: 260 }}
      role="img" aria-label="A stack of bars spaced either by one repeated unit or by irregular gaps, showing what visual rhythm looks like when it holds and when it breaks">
      <div style={{ background: "#FAF7F2", border: "1.5px dashed #24143055", borderRadius: 8, padding: 12, boxSizing: "border-box" }}>
        <div style={{ ...bar, marginBottom: gaps[0] }}>1</div>
        <div style={{ ...bar, marginBottom: gaps[1] }}>2</div>
        <div style={{ ...bar, marginBottom: gaps[2] }}>3</div>
        {n >= 4 && <div style={{ ...bar, marginBottom: gaps[3] }}>4</div>}
        {n >= 5 && <div style={bar}>5</div>}
      </div>
      <p style={{ marginTop: 12, fontSize: 12, color: "#241430cc" }}>
        {consistent ? `Every gap is ${spacing}px — a steady rhythm.` : "Gaps vary — rhythm breaks."} ({barCount} bars shown)
      </p>
    </div>
  );
}
